create or replace function public.enforce_file_ownership()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.id is distinct from old.id
     or new.owner_id is distinct from old.owner_id
     or new.legal_hold is distinct from old.legal_hold then
    raise exception 'files id, owner, and legal_hold are immutable';
  end if;

  if new.name is distinct from old.name then
    if old.legal_hold then
      raise exception 'cannot rename a file under legal hold';
    end if;

    if not public.is_org_admin()
       and new.owner_id is distinct from old.owner_id then
      raise exception 'only the owner or an org admin can rename a file';
    end if;
  end if;

  return new;
end;
$$;

