```sql
alter table public.notifications enable row level security;

-- R1: users can only read their own notifications
create policy notifications_select on public.notifications
  for select to authenticated
  using (user_id = (select auth.uid()));

-- R2: users can only update read_at on their own notifications, and cannot change
-- anything else (with check makes the row stay owned by the same user and keeps
-- all other columns as they are)
create policy notifications_update on public.notifications
  for update to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

-- R2: users can delete their own notifications
create policy notifications_delete on public.notifications
  for delete to authenticated
  using (user_id = (select auth.uid()));

-- R3 / R4: no insert policy exists for authenticated, and anon has no access at all
-- (R3: nobody can create notifications through the app; R4: anonymous visitors
-- cannot see or change anything). Defense in depth: also revoke the underlying
-- privileges so even a policy leak cannot be exploited.
revoke all on table public.notifications from anon;
revoke all on table public.notifications from authenticated;
revoke all on sequence public.notifications_id_seq from anon;
revoke all on sequence public.notifications_id_seq from authenticated;

grant select, update, delete on table public.notifications to authenticated;
grant usage, select on sequence public.notifications_id_seq to authenticated;

grant all on table public.notifications to service_role;
grant all on sequence public.notifications_id_seq to service_role;
