on public.requests
for insert
to authenticated
with check (
  created_by = auth.uid()
  and status = 'open'
  and public.is_resident_of(unit_id)
);

create policy "request_photos_insert_by_request_seer"
on public.request_photos
for insert
to authenticated
with check (public.can_see_request(request_id));

