```sql
alter table public.classes enable row level security;
alter table public.class_spots enable row level security;

create or replace function public.is_class_instructor(cid bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.classes c
    where c.id = cid
      and c.instructor_id = auth.uid()
  );
$$;

create or replace function public.can_enroll_in_class(cid bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.classes c
    where c.id = cid
      and c.instructor_id <> auth.uid()
      and (
        select count(*)::integer
        from public.class_spots s
        where s.class_id = c.id
          and s.status = 'enrolled'
      ) < c.capacity
  );
$$;

create or replace function public.enforce_class_spot_rules()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if auth.role() = 'service_role'
     or current_user = 'service_role'
     or current_user in ('postgres', 'supabase_admin')
     or coalesce(auth.jwt() ->> 'role', '') = 'service_role' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.user_id is distinct from auth.uid() then
      raise exception 'class_spots.user_id must be the authenticated user'
        using errcode = '42501';
    end if;
    if new.status not in ('enrolled', 'waitlisted') then
      raise exception 'class_spots.status must be enrolled or waitlisted'
        using errcode = '42501';
    end if;
    if new.status = 'enrolled' then
      if not public.can_enroll_in_class(new.class_id) then
        raise exception 'class is full, only waitlisted status is available'
          using errcode = '42501';
      end if;
    end if;
    return new;
  end if;

  if tg_op = 'UPDATE' then
    if old.class_id is distinct from new.class_id
       or old.user_id is distinct from new.user_id then
      raise exception 'only status can change on class_spots'
        using errcode = '42501';
    end if;
    if old.status = 'enrolled' then
      raise exception 'enrolled members cannot change status'
        using errcode = '42501';
    end if;
    if new.status = 'enrolled' then
      if not public.can_enroll_in_class(old.class_id) then
        raise exception 'no room in class to enroll'
          using errcode = '42501';
      end if;
    end if;
    return new;
  end if;

  return new;
end;
$$;

